insert into public.ingredients (name, category, cost_per_kg, source, nutrients)
select name, category, null, source, nutrients from seed
on conflict (lower(name)) do update set
  category = excluded.category,
  source = excluded.source,
  nutrients = (public.ingredients.nutrients - 'xanthophyll' - 'canthaxanthin') || excluded.nutrients;
